using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class MyTools
{
    [McpServerTool, Description("Returns a greeting for the given name.")]
    public static string Greet(string name) => $"Hello, {name}!";

    [McpServerTool, Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;
}

using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app-settings",
        Title = "Application Settings", MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/version", Name = "app-version",
        Title = "Application Version", MimeType = "text/plain")]
    public static string GetAppVersion() => "1.0.0";
}

